dtsPropsFor.Popover:
/** The element the popover hangs off. `null` is the closed state — `usePopover()` returns exactly this union. */
  anchor: HTMLElement | null;
  /** `menu`, `menu sizer`, `menu form` or `pal` — the stylesheet selects on these. */
  className: string;
  onClose: () => void;
  children: React.ReactNode;

dtsPropsFor.Menu:
/** The element the menu hangs off. `null` is the closed state. */
  anchor: HTMLElement | null;
  /** A separator, or a command. `on` draws a tick, `danger` colours it, `hint` adds a dim clause after the label. */
  items: Array<
    | { sep: true }
    | {
        label: string;
        run: () => void;
        on?: boolean;
        danger?: boolean;
        sep?: false;
        hint?: string;
        drag?: (e: React.DragEvent) => void;
      }
  >;
  onClose: () => void;

dtsPropsFor.NumInput:
value: string;
  onValue: (v: string) => void;
  /** The ↑/↓ step. Defaults to 1. */
  fine?: number;
  /** The ⌘↑/⌘↓ step. Defaults to 8x `fine`. */
  bigStep?: number;
  /** What an empty box counts from — the checkpoint's own number. */
  base?: number;
  onEnter?: () => void;
  /** Blur and Enter, for the boxes that snap on the way out. */
  onCommit?: () => void;
  placeholder?: string;
  disabled?: boolean;
  inputMode?: 'decimal' | 'numeric' | 'text';
  'aria-label'?: string;
  className?: string;
  id?: string;
  style?: React.CSSProperties;

dtsPropsFor.ErrorNote:
/** A bare sentence, or the API's split form: `error` is what a person reads, `detail` is what the server said. Renders nothing when falsy. */
  err: string | { error: string; detail?: string } | null | undefined;
  style?: React.CSSProperties;
